import{_ as r,a as e,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 52 艮：止在适当之处至54 归妹：看见关系中的位置与代价","description":"核读古籍，理解变革与建立、震动与止息、婚姻礼制、丰盛及羁旅处境。","frontmatter":{"title":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 52 艮：止在适当之处至54 归妹：看见关系中的位置与代价","description":"核读古籍，理解变革与建立、震动与止息、婚姻礼制、丰盛及羁旅处境。","splitFrom":"life/personal/yijing/hexagrams-49-56.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅","summary":"核读古籍，理解变革与建立、震动与止息、婚姻礼制、丰盛及羁旅处境。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 49 革：变化需要信任与时机至51 震：惊惧之后恢复分寸","link":"/life/personal/yijing/hexagrams-49-56-part-01"},"next":{"text":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 55 丰：盛大之中仍可能看不清至比较与自测","link":"/life/personal/yijing/hexagrams-49-56-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 49 革：变化需要信任与时机至51 震：惊惧之后恢复分寸","link":"/life/personal/yijing/hexagrams-49-56-part-01"},"next":{"text":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 55 丰：盛大之中仍可能看不清至比较与自测","link":"/life/personal/yijing/hexagrams-49-56-part-03"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-49-56-part-02.md","filePath":"life/personal/yijing/hexagrams-49-56-part-02.md"}'),o={name:"life/personal/yijing/hexagrams-49-56-part-02.md"};function d(s,t,i,p,l,g){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读-四十九至五十六-革、鼎、震、艮、渐、归妹、丰、旅-·-52-艮-止在适当之处至54-归妹-看见关系中的位置与代价" tabindex="-1">六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 52 艮：止在适当之处至54 归妹：看见关系中的位置与代价 <a class="header-anchor" href="#六十四卦详读-四十九至五十六-革、鼎、震、艮、渐、归妹、丰、旅-·-52-艮-止在适当之处至54-归妹-看见关系中的位置与代价" aria-label="Permalink to &quot;六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 52 艮：止在适当之处至54 归妹：看见关系中的位置与代价&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-49-56">返回分篇目录</a></p><p>这里保留《周易》卦辞、爻辞与《象传》大象的原貌，再用简体中文解释。白话均为现代概括，古注主要取王弼注、孔颖达疏《周易正义》，不是现代逐字译文。遇到异文、难字或不同解释时会注明；引文中的占断属于古代文本，不据以保证事件结果。</p><p>这八卦既有革鼎的制度变化，也有震艮的动静，更有渐、归妹中的婚姻礼制。读古代家庭与政治时，要同时看见思想资源和历史限制；现代借鉴必须说明转换的前提。</p><h2 id="gua-52" tabindex="-1">52 艮：止在适当之处 <a class="header-anchor" href="#gua-52" aria-label="Permalink to &quot;52 艮：止在适当之处 {#gua-52}&quot;">​</a></h2><p><strong>卦符：䷳｜上卦艮 ☶，下卦艮 ☶，两山相重。</strong>“艮”读 gèn，古注以止解释；与震的动相对，但并不主张永远静止。</p><p><strong>卦辞原文：</strong></p><blockquote><p>艮：艮其背，不獲其身，行其庭，不見其人，无咎。</p></blockquote><p><strong>白话概括：</strong> 止于背，不执取自身，行于庭中而不见人。这段难以逐字顺译，古注用“背不见物”说明让欲念在未萌时自然安止，反对已经对面相遇却强行阻隔。《彖传》的“时止则止，时行则行”是理解全卦的重要限制。</p><p><strong>六爻原文与简释（九三、六五从《正义》本）：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>艮其趾，无咎，利永貞。</td><td>步履尚未发动时能停下来，可少过失；持续守正不等于永不行动。</td></tr><tr><td>六二</td><td>艮其腓，不拯其隨，其心不快。</td><td>小腿受止，脚不能随之举起，内心不快；《正义》把此爻列为施止不得其所的情形。</td></tr><tr><td>九三</td><td>艮其限，列其夤，厲薰心。</td><td>腰际被阻，背脊如受分裂，忧危熏心；古注以强行割裂上下联系解释，显示“止”也会伤害。</td></tr><tr><td>六四</td><td>艮其身，无咎。</td><td>从自身整体处约束躁动，不把身心割裂；自止与强制他人停止，应分开讨论。</td></tr><tr><td>六五</td><td>艮其輔，言有序，悔亡。</td><td>节制口颊，言语有次序，减少悔恨；独立电子本另列“孚”，这里从“序”读。</td></tr><tr><td>上九</td><td>敦艮，吉。</td><td>以敦厚安定的方式止，能保持到最后；古注的“厚”区别于僵硬、强压的停止。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>兼山，艮；君子以思不出其位。</p></blockquote><p><strong>大象解释：</strong> 山各有其所，引出思虑与职责相称。可以讨论分寸和责任，但不能因此禁止人了解公共事务，或以地位为由剥夺思考权。</p><p><strong>整体读法与误区：</strong> 六爻依次写趾、腓、腰背、身体、口颊，是通过身体位置讨论止的方式，不是经络疗法或静坐动作教程。二、三爻出现不快与危险，说明僵硬压抑不是成功的止。今天可借鉴暂停冲动、整理语言、明确职责，同时保有必要的沟通和行动；若把“艮其背”译成对他人苦难视而不见，就丢失了“止其所”的分寸。</p><p><strong>经传对读：</strong> 二、三爻在身体中部写阻隔与不快，六五则在口颊处写有序语言，说明“止”既可能强断联系，也可能使表达更恰当。《正义》不把全部停止都判为吉，反而反复辨别止处是否合适。与震连读，可问行动有没有失去准则、停止有没有伤及必要联系，动静由此都需要具体判断。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%89%AE" target="_blank" rel="noopener noreferrer">《周易·艮》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/05%E8%89%AE" target="_blank" rel="noopener noreferrer">《周易正义》卷五·艮</a>。</p><h2 id="gua-53" tabindex="-1">53 渐：进展要有承接的地方 <a class="header-anchor" href="#gua-53" aria-label="Permalink to &quot;53 渐：进展要有承接的地方 {#gua-53}&quot;">​</a></h2><p><strong>卦符：䷴｜上卦巽 ☴（木、风），下卦艮 ☶（山、止）。</strong> 山上树木渐长，六爻又连续用鸿雁落脚的位置写进展，形成鲜明的叙事线。</p><p><strong>卦辞原文：</strong></p><blockquote><p>漸：女歸吉，利貞。</p></blockquote><p><strong>白话概括：</strong> 女子依礼出嫁为吉，利于守正。《正义》由婚礼须备礼再行解释“不速而进”，不是说所有慢都正确，也不只把渐当成抽象耐心。“归”在古代婚姻语言中指女子出嫁，应先识别其制度背景，再谈现代过程管理。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>鴻漸于干，小子厲，有言，无咎。</td><td>鸿雁先到水岸，落脚未稳，可能受威胁与议论；“干”指水涯，初步进展尚需保护。</td></tr><tr><td>六二</td><td>鴻漸于磐，飲食衎衎，吉。</td><td>到安稳磐石，有食可安乐，“衎衎”读 kàn kàn；进展的质量也包括基本支持是否稳定。</td></tr><tr><td>九三</td><td>鴻漸于陸，夫征不復，婦孕不育，凶；利禦寇。</td><td>过度外出与关系失养并列，处境凶；适宜共同防护。婚育意象不可用来诊断生育能力。</td></tr><tr><td>六四</td><td>鴻漸于木，或得其桷，无咎。</td><td>雁不易安于树木，却可能找到平直枝干；“桷”本为方椽，借以说明需适配的承接处。</td></tr><tr><td>九五</td><td>鴻漸于陵，婦三歲不孕，終莫之勝，吉。</td><td>到较高山陵，关系曾长期受阻而终能相通；“三岁”属于叙事占辞，不能许诺怀孕期限。</td></tr><tr><td>上九</td><td>鴻漸于陸，其羽可用為儀，吉。</td><td>雁羽可用于礼仪，重心由落脚转到秩序与可为典范；此据所核电子本保留“陆”。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>山上有木，漸；君子以居賢德，善俗。</p></blockquote><p><strong>大象解释：</strong> 积累贤德、改善风俗需要过程。《正义》还解释为使贤者居位，以文德渐化，而不靠突然的威刑强迫改变。</p><p><strong>整体读法与误区：</strong> 逐爻可问“雁落在哪里，这里是否适合安身”，比只看高度更能读出渐义。三爻已经有凶，说明位置升高不代表条件更好；六四则显示临时调整也有价值。现代可借来审视技能成长、关系建立或习惯改变的支撑条件。古代婚礼的次序不应原封不动用于今天择偶，更不能以“渐”要求人等待一段持续伤害自己的关系。</p><p><strong>经传对读：</strong> 六二能够饮食，六四能够找到适宜枝干，都先解决安身条件，再谈进一步上升；九三则同时写离群与护卫。《小象》说“顺相保”，使相互保护成为应对凶境的线索。鸿雁的路线可以帮助记忆爻辞，但并不等于自然观察记录，不能强令每个栖止地点都符合现代鸟类学。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%BC%B8" target="_blank" rel="noopener noreferrer">《周易·渐》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/05%E6%BC%B8" target="_blank" rel="noopener noreferrer">《周易正义》卷五·渐</a>。</p><h2 id="gua-54" tabindex="-1">54 归妹：看见关系中的位置与代价 <a class="header-anchor" href="#gua-54" aria-label="Permalink to &quot;54 归妹：看见关系中的位置与代价 {#gua-54}&quot;">​</a></h2><p><strong>卦符：䷵｜上卦震 ☳（雷、长男），下卦兑 ☱（泽、少女）。</strong> 卦名涉及女子出嫁，古注特别联系随嫁、媵妾等制度，不能直接改写成现代自由恋爱。</p><p><strong>卦辞原文：</strong></p><blockquote><p>歸妹：征凶，无攸利。</p></blockquote><p><strong>白话概括：</strong> 在此种关系格局中贸然推进有凶，尚无所利。《正义》以非正配、身份不对等解释；这揭示了古代婚姻位置的限制，也明显包含维护嫡庶秩序的立场。现代阅读首先应辨认权利不平等，而不是教人接受从属地位。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>歸妹以娣，跛能履，征吉。</td><td>以随嫁娣的身份出嫁，如有行动限制仍能走路；“娣”涉及古代婚制，不是给现代婚姻中的第三者分类。</td></tr><tr><td>九二</td><td>眇能視，利幽人之貞。</td><td>视力受限仍能见，处于幽隐位置仍可保持自己的操守；不要把身体差异等同道德缺陷。</td></tr><tr><td>六三</td><td>歸妹以須，反歸以娣。</td><td>“须”有等待等训释，《正义》取待时；欲进却条件不合，退回以原有身份等待，呈现制度束缚。</td></tr><tr><td>九四</td><td>歸妹愆期，遲歸有時。</td><td>婚期延后，仍待适当时机；“愆”读 qiān，不应据此给晚婚者贴上失败标签。</td></tr><tr><td>六五</td><td>帝乙歸妹，其君之袂，不如其娣之袂良，月幾望，吉。</td><td>王室婚嫁中主妇衣袖不如随嫁者华美，地位与外饰并不等同；“帝乙”宜保留历史叙事层次。</td></tr><tr><td>上六</td><td>女承筐无實，士刲羊无血，无攸利。</td><td>女子捧空筐，男子宰羊却无血，礼仪只剩形式；“刲”读 kuī，关键是缺少使关系成立的实质。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>澤上有雷，歸妹；君子以永終知敝。</p></blockquote><p><strong>大象解释：</strong> 从能否长久终成来认识潜在弊端。初时的愉悦与冲动，不能替代对长期关系结构的判断。</p><p><strong>整体读法与误区：</strong> 本卦有“征凶”，初九却有“征吉”，显示卦辞与爻辞针对层次不同，不可简单以一字定整个人生。现代可以讨论一段关系是否有真实承诺、清楚身份、平等选择和退出能力；这些问题需要现实证据。不能把古注关于媵妾的安排转为当代女性应守从属位的伦理，更不能用卦替别人决定婚姻。</p><p><strong>经传对读：</strong> 初九、九二分别以跛足、眇目比附受限处境，四爻容许等待，五爻讨论服饰与身份，最后以空筐无血批评形式失实。六爻因此不是同一个婚礼的完整时间表。尤其空有仪式却无实质的结尾，可以回头检验卦辞为何警惕推进，同时保留对古代婚制不平等的批判距离。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AD%B8%E5%A6%B9" target="_blank" rel="noopener noreferrer">《周易·归妹》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/05%E6%AD%B8%E5%A6%B9" target="_blank" rel="noopener noreferrer">《周易正义》卷五·归妹</a>。</p>',43)])])}const k=r(o,[["render",d]]);export{c as __pageData,k as default};
